#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long total = 0;
    for (long long x : a) total += x;
    if (total % 2) {
        cout << "no\n";
    } else {
        int half = (int)(total / 2);
        vector<char> can(half + 1, 0);
        can[0] = 1;
        for (long long x : a) {
            for (int s = half; s >= x; s--) {
                if (can[s - x]) can[s] = 1;
            }
        }
        cout << (can[half] ? "yes" : "no") << "\n";
    }

    return 0;
}

